import clsx from 'clsx';

const statusClasses = {
  success: 'bg-green-100 text-green-800',
  warning: 'bg-amber-100 text-amber-800',
  error: 'bg-red-100 text-red-800',
} as const;

function Pill({ status, active }: { status: keyof typeof statusClasses; active?: boolean }) {
  return (
    <span className={clsx('rounded-full px-2 py-0.5 text-xs', statusClasses[status], active && 'ring-2 ring-offset-1')}>
      {status}
    </span>
  );
}

// lib/utils.ts
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// usage: consumer overrides win predictably
<Button className={cn('px-4 py-2', isWide && 'w-full', className)} />

import { cn } from '@/lib/utils';

export function Card({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="card"
      className={cn('rounded-xl border bg-card p-6 text-card-foreground shadow-sm', className)}
      {...props}
    />
  );
}

